import logging
import uuid
from typing import Any

from app.schemas.handover import EvidenceReference, HandoverClaim, HandoverSection

logger = logging.getLogger(__name__)


class HandoverValidator:
    """Validates handover claims generated by LLM against real database entities and evidence.

    Ensures:
    1. Every claim references genuine database entities (KnowledgeItem, Task, Evidence).
    2. The referenced entity possesses actual supporting evidence.
    3. Dropping or flagging claims that cite fabricated or ungrounded item IDs.
    4. Visually classifying claims as approved, pending, explicit_fact, or ai_inference.
    """

    def validate_sections(
        self,
        raw_sections: dict[str, Any],
        grounding_items_map: dict[uuid.UUID, dict[str, Any]],
        drop_unverified: bool = False,
    ) -> tuple[dict[str, HandoverSection], list[EvidenceReference], int, int, int]:
        """Validates all raw section outputs and constructs typed, evidence-linked HandoverSection objects.

        Returns:
            (sections_dict, all_evidence_refs, total_claims, verified_claims, unverified_claims)
        """
        validated_sections: dict[str, HandoverSection] = {}
        all_evidence_map: dict[uuid.UUID, EvidenceReference] = {}
        total_claims = 0
        verified_claims = 0
        unverified_claims = 0

        for key, sec_data in raw_sections.items():
            title = sec_data.get("title", key.replace("_", " ").title())
            narrative = sec_data.get("narrative", "")
            raw_statements = sec_data.get("statements", [])

            section_claims: list[HandoverClaim] = []
            section_evidence_map: dict[uuid.UUID, EvidenceReference] = {}

            for stmt in raw_statements:
                text = stmt.get("text", "").strip()
                if not text:
                    continue

                raw_ids = stmt.get("item_ids", [])
                valid_uuids: list[uuid.UUID] = []
                for rid in raw_ids:
                    try:
                        valid_uuids.append(uuid.UUID(str(rid)))
                    except (ValueError, TypeError):
                        continue

                # Check references against grounding_items_map
                matched_items = [
                    grounding_items_map[uid] for uid in valid_uuids if uid in grounding_items_map
                ]
                has_invalid_refs = len(matched_items) < len(valid_uuids) or len(valid_uuids) == 0

                # Check evidence availability
                claim_evidences: list[EvidenceReference] = []
                for item in matched_items:
                    ev_list = item.get("evidences", [])
                    for ev in ev_list:
                        claim_evidences.append(ev)
                        section_evidence_map[ev.evidence_id] = ev
                        all_evidence_map[ev.evidence_id] = ev

                has_evidence = len(claim_evidences) > 0

                total_claims += 1

                # If claim references non-existent items or has zero evidence
                if has_invalid_refs or not has_evidence:
                    unverified_claims += 1
                    if drop_unverified:
                        logger.warning(
                            "Dropping ungrounded claim: %s (refs: %s)", text[:80], raw_ids
                        )
                        continue

                    # Flag statement as unverified
                    section_claims.append(
                        HandoverClaim(
                            text=text,
                            referenced_item_ids=[item["id"] for item in matched_items],
                            verified=False,
                            evidence_references=claim_evidences,
                            review_status="pending",
                            origin="ai_inference",
                            flagged_unverified=True,
                        )
                    )
                else:
                    verified_claims += 1
                    # Determine review status
                    statuses = {item.get("review_status", "pending") for item in matched_items}
                    if "rejected" in statuses:
                        claim_status = "rejected"
                    elif all(s == "approved" for s in statuses):
                        claim_status = "approved"
                    else:
                        claim_status = "pending"

                    # Determine origin
                    origins = {item.get("origin", "explicit_fact") for item in matched_items}
                    claim_origin = "ai_inference" if "ai_inference" in origins else "explicit_fact"

                    section_claims.append(
                        HandoverClaim(
                            text=text,
                            referenced_item_ids=[item["id"] for item in matched_items],
                            verified=True,
                            evidence_references=claim_evidences,
                            review_status=claim_status,
                            origin=claim_origin,
                            flagged_unverified=False,
                        )
                    )

            validated_sections[key] = HandoverSection(
                key=key,
                title=title,
                narrative=narrative,
                claims=section_claims,
                evidence_references=list(section_evidence_map.values()),
                stats={
                    "total_claims": len(section_claims),
                    "verified_claims": sum(1 for c in section_claims if c.verified),
                    "unverified_claims": sum(1 for c in section_claims if not c.verified),
                    "evidence_count": len(section_evidence_map),
                },
            )

        return (
            validated_sections,
            list(all_evidence_map.values()),
            total_claims,
            verified_claims,
            unverified_claims,
        )


_global_validator: HandoverValidator | None = None


def get_handover_validator() -> HandoverValidator:
    global _global_validator
    if _global_validator is None:
        _global_validator = HandoverValidator()
    return _global_validator
